// Normalise a filename or label to the match token (GJ-2 R and GJ2-RIGHT -> "GJ2R").
export const polkiCanon = (s: string): string =>
  s.replace(/\.[a-z0-9]+$/i, "").toUpperCase().replace(/RIGHT/g, "R").replace(/LEFT/g, "L").replace(/[^A-Z0-9]/g, "");
